    "date_created" = EXCLUDED."date_created",
    "land_area_sq_km" = EXCLUDED."land_area_sq_km",
    "seal_image_url" = EXCLUDED."seal_image_url",
    "flag_image_url" = EXCLUDED."flag_image_url",
    "official_website_url" = EXCLUDED."official_website_url",
    "finance_ministry_url" = EXCLUDED."finance_ministry_url",
    "assembly_website_url" = EXCLUDED."assembly_website_url",
    "inec_info_url" = EXCLUDED."inec_info_url",
    "contact_address" = EXCLUDED."contact_address",
    "contact_phone" = EXCLUDED."contact_phone",
    "contact_email" = EXCLUDED."contact_email",
    "complaint_portal_url" = EXCLUDED."complaint_portal_url",
    "whistleblower_url" = EXCLUDED."whistleblower_url",
    "twitter_url" = EXCLUDED."twitter_url",
    "facebook_url" = EXCLUDED."facebook_url",
    "instagram_url" = EXCLUDED."instagram_url",
    "youtube_url" = EXCLUDED."youtube_url",
    "news_url" = EXCLUDED."news_url",
