INSERT INTO "state_profiles" ("state_code", "about", "motto", "date_created", "land_area_sq_km", "seal_image_url", "flag_image_url", "official_website_url", "finance_ministry_url", "assembly_website_url", "inec_info_url", "contact_address", "contact_phone", "contact_email", "complaint_portal_url", "whistleblower_url", "twitter_url", "facebook_url", "instagram_url", "youtube_url", "news_url")
VALUES
  ('benue', 'Benue is a state in Nigeria''s North Central region, named after the Benue River, and is known for its agricultural output with major ethnic groups including the Tiv, Idoma, and Igede. Its capital is Makurdi.', 'Food Basket of the Nation', '1976-02-03'::date, 34059, '/states/seals/benue.png', NULL, 'https://benuestate.gov.ng/', NULL, NULL, NULL, 'Government House, Kashim Ibrahim Way, Old GRA, Makurdi, Benue State', NULL, 'info@benuestate.gov.ng', NULL, NULL, 'https://x.com/benuestategovt', NULL, NULL, NULL, NULL),
  ('kogi', 'Kogi is a state in Nigeria''s North Central region with its capital at Lokoja, located at the confluence of the Niger and Benue rivers. It borders ten other states, more than any other Nigerian state.', 'The Confluence State', '1991-08-27'::date, 29833, '/states/seals/kogi.png', NULL, 'https://kogistate.gov.ng/', NULL, NULL, NULL, 'Ministry of Information & Communications, State Secretariat, Lokoja, Kogi State', NULL, 'info@kogistate.gov.ng', NULL, NULL, 'https://x.com/kogistategovng', 'https://www.facebook.com/kogistategovt/', 'https://www.instagram.com/kogistategovng', NULL, NULL),
  ('kwara', 'Kwara is a state in north-central Nigeria with its capital at Ilorin, bordered by Kogi, Niger, Ekiti, Osun, and Oyo states as well as the Republic of Benin. Its economy centres on agriculture and services.', 'State of Harmony', '1967-05-27'::date, 36825, '/states/seals/kwara.png', NULL, 'https://kwarastate.gov.ng/', 'https://mof.kw.gov.ng/', 'https://hoa.kw.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, 'https://x.com/followkwsg', 'https://www.facebook.com/followkwsg/', NULL, NULL, NULL),
  ('nasarawa', 'Nasarawa is a state in Nigeria''s North Central region with its capital at Lafia, established in 1996 from the former Plateau State. Its economy is based largely on agriculture and solid minerals.', 'Home of Solid Minerals', '1996-10-01'::date, 26256, '/states/seals/nasarawa.svg', NULL, 'https://nasarawastate.gov.ng/', NULL, NULL, NULL, 'Nasarawa State Government House, Shendam Road, Lafia, Nasarawa State', NULL, 'info@nasarawastate.gov.ng', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('niger', 'Niger is the largest state in Nigeria by land area, located in the North Central region with its capital at Minna. Its economy depends on agriculture and hydroelectric power generation from major dams including Kainji, Shiroro, and Jebba.', 'The Power State', '1976-02-03'::date, 76363, '/states/seals/niger.png', NULL, 'https://nigerstate.gov.ng/', NULL, NULL, NULL, 'Yakubu Lame Road, Minna 920101, Niger State', NULL, 'info@nigerstate.gov.ng', NULL, NULL, 'https://x.com/NigerStateNG', 'https://www.facebook.com/NigerStateNG/', NULL, NULL, NULL),
  ('plateau', 'Plateau is a state in Nigeria''s North Central region with its capital at Jos, named for the Jos Plateau and known for its hills, rock formations, and relatively cool climate. It is a center of tin mining and tourism.', 'Home of Peace and Tourism', '1976-02-03'::date, 30913, '/states/seals/plateau.jpg', NULL, 'https://plateaustate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.plateaustate.gov.ng/news/'),
  ('fct', 'The Federal Capital Territory is a federal territory in central Nigeria that contains the nation''s capital, Abuja. It was created in 1976 from parts of surrounding states to serve as a centrally located, neutral seat of government.', 'Centre of Unity', '1976-02-03'::date, 7315, '/states/seals/fct.png', '/states/flags/fct.svg', 'https://fcta.gov.ng/', NULL, NULL, NULL, 'Plot 1, Kapital Street, Area 11, Garki, PMB 24, FCT Abuja', NULL, NULL, NULL, NULL, 'https://x.com/OfficialFCTA', 'https://www.facebook.com/fcta.gov.ng', 'https://www.instagram.com/officialfcta/', NULL, 'https://www.fcta.gov.ng/news/'),
  ('adamawa', 'Adamawa State is a state in north-eastern Nigeria with its capital at Yola. It was created in 1991 from the former Gongola State and is named after the historic Adamawa Emirate.', 'Land of Beauty', '1991-08-27'::date, 36917, '/states/seals/adamawa.png', NULL, 'https://adamawastate.gov.ng/', NULL, NULL, NULL, 'Adamawa State Government House, Dougirei, Yola, Adamawa State', NULL, 'info@adamawastate.gov.ng', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('bauchi', 'Bauchi State is a state in north-eastern Nigeria with its capital at Bauchi. It was created in 1976 from the former North-Eastern State and originally included territory that became Gombe State in 1996.', 'Pearl of Tourism', '1976-02-03'::date, 45893, '/states/seals/bauchi.png', NULL, 'https://home.bauchistate.gov.ng/', NULL, NULL, NULL, 'Government House, Bauchi, Bauchi State', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('borno', 'Borno State is a state in north-eastern Nigeria with its capital at Maiduguri. It was created in 1976 and is the largest Nigerian state by land area.', 'Home of Peace', '1976-02-03'::date, 70898, '/states/seals/borno.svg', NULL, 'https://bornostate.gov.ng/', 'https://pfm.bo.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('gombe', 'Gombe State is a state in north-eastern Nigeria with its capital at Gombe. It was created in 1996 from part of the former Bauchi State and is nicknamed the ''Jewel in the Savannah''.', 'Jewel in the Savannah', '1996-10-01'::date, 18768, '/states/seals/gombe.png', NULL, 'https://gombestate.gov.ng/', NULL, NULL, NULL, 'Government House, Jibiro Road, Gombe, Gombe State', NULL, 'info@gombestate.gov.ng', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('taraba', 'Taraba State is a state in north-eastern Nigeria with its capital at Jalingo. It was created in 1991 from the former Gongola State and is named after the Taraba River.', 'Nature''s Gift to the Nation', '1991-08-27'::date, 54473, '/states/seals/taraba.png', NULL, 'https://tarabastate.gov.ng/', NULL, NULL, NULL, NULL, NULL, 'info@tarabastate.gov.ng', NULL, NULL, 'https://x.com/OfficialTaraba', NULL, NULL, NULL, NULL),
  ('yobe', 'Yobe State is a state in north-eastern Nigeria with its capital at Damaturu. It was created in 1991, carved out of the former Borno State.', 'Pride of the Sahel', '1991-08-27'::date, 45502, '/states/seals/yobe.png', NULL, 'https://yobestate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('jigawa', 'Jigawa State is a state in northwestern Nigeria with its capital at Dutse. It was created on 27 August 1991 from part of the old Kano State.', 'The New World', '1991-08-27'::date, 23154, NULL, '/states/flags/jigawa.svg', 'https://jigawastate.gov.ng/', 'https://jsbepd.org/', NULL, NULL, 'Jigawa State Government House, Dutse, Jigawa State', NULL, 'webmaster@jigawastate.gov.ng', NULL, NULL, NULL, 'https://www.facebook.com/jigawastategovernment/', NULL, NULL, NULL),
  ('kaduna', 'Kaduna State is a state in northwestern Nigeria with its capital at Kaduna. It was created on 27 May 1967 and is known as a centre of learning.', 'Centre of Learning', '1967-05-27'::date, 46053, '/states/seals/kaduna.png', NULL, 'https://kdsg.gov.ng/', NULL, NULL, NULL, 'Sir Kashim Ibrahim House, 44 Polytechnic Road, Badiko, Kaduna, Kaduna State, Nigeria', '0817 0189 999', 'info@kdsg.gov.ng', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('kano', 'Kano State is a state in northwestern Nigeria with its capital at Kano. It was created on 27 May 1967 and is a major centre of commerce.', 'Centre of Commerce', '1967-05-27'::date, 20131, '/states/seals/kano.png', NULL, 'https://kanostate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://x.com/kanostateng', 'https://www.facebook.com/kanogovt/', 'https://www.instagram.com/officialkanostategovernment/', NULL, NULL),
  ('katsina', 'Katsina State is a state in northwestern Nigeria with its capital at Katsina. It was created on 23 September 1987 from part of the old Kaduna State.', 'Home of Hospitality', '1987-09-23'::date, 24192, '/states/seals/katsina.png', NULL, 'https://katsinastate.gov.ng/', NULL, 'https://www.houseofassembly.kt.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('kebbi', 'Kebbi State is a state in northwestern Nigeria with its capital at Birnin Kebbi. It was created on 27 August 1991 from part of the old Sokoto State.', 'Land of Equity', '1991-08-27'::date, 36800, '/states/seals/kebbi.png', NULL, 'https://www.kebbistate.gov.ng/', NULL, NULL, NULL, 'Gwadangaji Secretariat Complex, Birnin Kebbi, Kebbi State', NULL, 'info@kebbistate.gov.ng', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('sokoto', 'Sokoto State is a state in northwestern Nigeria with its capital at Sokoto. It was created on 3 February 1976 and is known as the Seat of the Caliphate.', 'Seat of the Caliphate', '1976-02-03'::date, 25973, '/states/seals/sokoto.png', NULL, 'https://sokotostate.gov.ng/', 'https://mof.sk.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://sokotostate.gov.ng/news/'),
  ('zamfara', 'Zamfara State is a state in northwestern Nigeria with its capital at Gusau. It was created on 1 October 1996 from part of the old Sokoto State.', 'Farming is Our Pride', '1996-10-01'::date, 39762, '/states/seals/zamfara.jpg', NULL, 'https://zamfara.gov.ng/', NULL, 'https://zsha.zamfara.gov.ng/', NULL, NULL, NULL, 'info@zamfara.gov.ng', NULL, NULL, NULL, NULL, NULL, NULL, 'https://zamfara.gov.ng/news/'),
  ('abia', 'Abia is a state in the South-East geopolitical zone of Nigeria, created in 1991 from part of Imo State, with its capital at Umuahia. Its largest city, Aba, is a major commercial and manufacturing hub.', 'God''s Own State', '1991-08-27'::date, 6320, '/states/seals/abia.png', NULL, 'https://abiastate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('anambra', 'Anambra is a state in the South-East geopolitical zone of Nigeria, created in 1991 from the former Anambra State, with its capital at Awka. Onitsha and Nnewi are major commercial and industrial centres within the state.', 'Light of the Nation', '1991-08-27'::date, 4844, '/states/seals/anambra.png', '/states/flags/anambra.png', 'https://anambrastate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('ebonyi', 'Ebonyi is a state in the South-East geopolitical zone of Nigeria, created in 1996 from parts of Abia and Enugu States, with its capital at Abakaliki. Its economy is predominantly agricultural, known for rice, yam and cassava production.', 'Salt of the Nation', '1996-10-01'::date, 6400, '/states/seals/ebonyi.png', NULL, 'https://ebonyistate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://twitter.com/Ebonyi_State', 'https://www.facebook.com/ebonyi.state.government.ng', 'https://www.instagram.com/ebonyi.state.gov.ng/', 'https://www.youtube.com/channel/UCAMvkIj70DwbZ6m827M2paw', NULL),
  ('enugu', 'Enugu is a state in the South-East geopolitical zone of Nigeria, created in 1991 from part of the old Anambra State, with its capital at Enugu city. The state and its capital are historically associated with coal mining, which gave rise to the nickname ''Coal City State''.', 'Coal City State', '1991-08-27'::date, 7161, '/states/seals/enugu.png', NULL, 'https://enugustate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('imo', 'Imo is a state in the South-East geopolitical zone of Nigeria, created in 1976, with its capital at Owerri. Its economy is based on agriculture (notably palm produce) as well as crude oil and natural gas.', 'Eastern Heartland', '1976-02-03'::date, 5530, '/states/seals/imo.png', '/states/flags/imo.svg', 'https://imostate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('akwa_ibom', 'Akwa Ibom is a state in the South South region of Nigeria, located in the coastal Niger Delta with its capital at Uyo. It was created on 23 September 1987 from the former Cross River State and is a major oil-producing state.', 'Land of Promise', '1987-09-23'::date, 7081, '/states/seals/akwa_ibom.jpg', NULL, 'https://akwaibomstate.gov.ng/', 'https://www.aksminfinance.ak.gov.ng/', NULL, NULL, NULL, NULL, 'info@akwaibomstate.gov.ng', NULL, NULL, 'https://x.com/aksgovt', 'https://www.facebook.com/aksgovt/', 'https://www.instagram.com/akwaibomstategovt/', NULL, NULL),
  ('bayelsa', 'Bayelsa is a state in the South South region of Nigeria, located in the core Niger Delta with its capital at Yenagoa. It was created on 1 October 1996 from part of Rivers State and is a major oil-producing state.', 'Truth, Service and Justice', '1996-10-01'::date, 10773, '/states/seals/bayelsa.webp', '/states/flags/bayelsa.svg', 'https://bayelsastate.gov.ng/', 'https://www.mof.by.gov.ng/', NULL, NULL, 'Government Secretariat, Yenagoa', '+234 806 873 4449', 'info@bayelsastate.gov.ng', NULL, NULL, NULL, NULL, NULL, NULL, 'https://bayelsastate.gov.ng/news/'),
  ('cross_river', 'Cross River is a state in the South South region of Nigeria, bordering Cameroon, with its capital at Calabar. It was created on 27 May 1967 and is known for tourism and its rainforests.', 'The People''s Paradise', '1967-05-27'::date, 20156, '/states/seals/cross_river.jpg', NULL, 'https://www.crossriverstate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('delta', 'Delta is a state in the South South region of Nigeria, located in the Niger Delta with its capital at Asaba and its largest city Warri. It was created on 27 August 1991 from the former Bendel State and is a major oil and gas producer.', NULL, '1991-08-27'::date, 17698, '/states/seals/delta.png', NULL, 'https://deltastate.gov.ng/', NULL, NULL, NULL, 'Government House, P.M.B. 5001, Asaba, Delta State', '+2348062156341', 'admin@deltastate.gov.ng', NULL, NULL, 'https://twitter.com/DSGovernment', 'https://www.facebook.com/DSGovernment/', NULL, NULL, NULL),
  ('edo', 'Edo is a state in the South South region of Nigeria, with its capital at Benin City. It was created on 27 August 1991 from the former Bendel State and is the historic home of the Benin Kingdom.', 'Heartbeat of Nigeria', '1991-08-27'::date, 19559, '/states/seals/edo.png', NULL, 'https://edostate.gov.ng/', NULL, NULL, NULL, 'Government House Complex, G.R.A, Benin City, Edo State', NULL, 'info@edostate.gov.ng', NULL, NULL, 'https://x.com/EdoStateGovt', 'https://www.facebook.com/EdoStateGovt/', NULL, NULL, NULL),
  ('rivers', 'Rivers is a state in the South South region of Nigeria, located in the Niger Delta with its capital at Port Harcourt. It was created on 27 May 1967 and is one of Nigeria''s leading oil and gas producing states.', 'Treasure Base of the Nation', '1967-05-27'::date, 11077, NULL, NULL, 'https://www.riversstate.gov.ng/', NULL, NULL, NULL, NULL, NULL, 'info@riversstate.gov.ng', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('ekiti', 'Ekiti State is a state in southwestern Nigeria, created on 1 October 1996 from part of the old Ondo State, with Ado-Ekiti as its capital. It is known for its predominantly Yoruba Ekiti people and a strong educational tradition.', 'Land of Honour and Integrity', '1996-10-01'::date, 6353, '/states/seals/ekiti.jpg', '/states/flags/ekiti.gif', 'https://www.ekitistate.gov.ng/', NULL, 'https://www.hoa.ek.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, 'https://x.com/ekitistategov', 'https://www.facebook.com/ekitistategov/', NULL, NULL, NULL),
  ('lagos', 'Lagos State is a state in southwestern Nigeria created on 27 May 1967, and is the smallest in area but the most populous state in the country. Its administrative capital is Ikeja, and it is Nigeria''s primary commercial and financial hub.', 'Centre of Excellence', '1967-05-27'::date, 3577, '/states/seals/lagos.svg', '/states/flags/lagos.svg', 'https://lagosstate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://x.com/followlasg', 'https://www.facebook.com/followlasg', 'https://www.instagram.com/lagosstategovt/', NULL, NULL),
  ('ogun', 'Ogun State is a state in southwestern Nigeria created on 3 February 1976, with Abeokuta as its capital. Nicknamed the Gateway State, it borders the Republic of Benin and is one of Nigeria''s most industrialised states.', 'Gateway State', '1976-02-03'::date, 16980.55, '/states/seals/ogun.png', '/states/flags/ogun.jpg', 'https://ogunstate.gov.ng/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://x.com/OGSG_Official', 'https://www.facebook.com/ogsgofficial', 'https://www.instagram.com/ogsgofficial/', NULL, NULL),
  ('ondo', 'Ondo State is a state in southwestern Nigeria created on 3 February 1976, with Akure as its capital. Nicknamed the Sunshine State, it is an oil-producing coastal state along the Atlantic.', 'Sunshine State', '1976-02-03'::date, 15500, '/states/seals/ondo.png', '/states/flags/ondo.png', 'https://ondostate.gov.ng/', NULL, NULL, NULL, 'Governor''s Office, Alagbaka, Akure, Ondo State', NULL, 'info@ondostate.gov.ng', NULL, NULL, 'https://twitter.com/ondostategovt', 'https://www.facebook.com/ondostategovt', 'https://www.instagram.com/ondostategovt', 'https://www.youtube.com/@ondostategovt', NULL),
  ('osun', 'Osun State is a state in southwestern Nigeria created on 27 August 1991 from part of the old Oyo State, with Osogbo as its capital. Nicknamed the State of the Living Spring, it is known for the Osun-Osogbo Sacred Grove, a UNESCO World Heritage Site.', 'State of the Living Spring', '1991-08-27'::date, 9251, '/states/seals/osun.png', '/states/flags/osun.svg', 'https://www.osunstate.gov.ng/', NULL, NULL, NULL, 'Bola Ige House, State Secretariat, Abere, Osogbo, Osun State', NULL, NULL, NULL, NULL, 'https://x.com/Osun_State_Gov', 'https://www.facebook.com/OsunstateGov/', NULL, NULL, NULL),
  ('oyo', 'Oyo State is a state in southwestern Nigeria created on 3 February 1976, with Ibadan as its capital. Nicknamed the Pace Setter State, it is an inland state and a major centre of Yoruba culture and commerce.', 'Pace Setter State', '1976-02-03'::date, 28454, '/states/seals/oyo.png', '/states/flags/oyo.svg', 'https://oyostate.gov.ng/', NULL, NULL, NULL, 'Oyo State Government Secretariat, Agodi, Ibadan, Oyo State', NULL, 'info@oyostate.gov.ng', NULL, NULL, 'https://twitter.com/oyostategovt', NULL, NULL, NULL, NULL)
